<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Calculator</title>
<style>
  body { font-family: sans-serif; display: flex; justify-content: center; padding: 20px; }
  .calc { width: 280px; }
  #display { width: 100%; box-sizing: border-box; font-size: 24px; padding: 8px; text-align: right; margin-bottom: 10px; }
  .row { display: flex; gap: 6px; margin-bottom: 6px; }
  .row button { flex: 1; font-size: 20px; padding: 12px 0; cursor: pointer; }
  .row button:active { background: #ccc; }
</style>
</head>
<body>
<div class="calc">
  <input id="display" type="text" readonly value="0">
  <div class="row">
    <button data-k="7">7</button>
    <button data-k="8">8</button>
    <button data-k="9">9</button>
    <button data-k="/">/</button>
  </div>
  <div class="row">
    <button data-k="4">4</button>
    <button data-k="5">5</button>
    <button data-k="6">6</button>
    <button data-k="*">*</button>
  </div>
  <div class="row">
    <button data-k="1">1</button>
    <button data-k="2">2</button>
    <button data-k="3">3</button>
    <button data-k="-">-</button>
  </div>
  <div class="row">
    <button data-k="0">0</button>
    <button data-k=".">.</button>
    <button data-k="=">=</button>
    <button data-k="+">+</button>
  </div>
  <div class="row">
    <button id="clear" style="flex:1">Clear</button>
    <button id="sqrt" style="flex:1">√</button>
    <button id="square" style="flex:1">^2</button>
    <button id="reciprocal" style="flex:1">1/x</button>
  </div>
</div>
<script>
(function () {
  var display = document.getElementById('display');
  var expr = '';

  function show(v) { display.value = String(v); }

  function calc() {
    try {
      if (expr === '') return show('0');
      var r = Function('return (' + expr + ')')();
      if (r === undefined || r === null || isNaN(r) || !isFinite(r)) throw new Error('bad');
      show(r);
      expr = String(r);
    } catch (e) {
      show('Error');
      expr = '';
    }
  }

  function sqrt() {
    try {
      var v = parseFloat(display.value);
      if (isNaN(v)) throw new Error('bad');
      var r = Math.sqrt(v);
      if (isNaN(r) || !isFinite(r)) throw new Error('bad');
      show(r);
      expr = String(r);
    } catch (e) {
      show('Error');
      expr = '';
    }
  }

  function square() {
    try {
      var v = parseFloat(display.value);
      if (isNaN(v)) throw new Error('bad');
      var r = v * v;
      if (isNaN(r) || !isFinite(r)) throw new Error('bad');
      show(r);
      expr = String(r);
    } catch (e) {
      show('Error');
      expr = '';
    }
  }

  function reciprocal() {
    try {
      var v = parseFloat(display.value);
      if (isNaN(v) || v === 0) throw new Error('bad');
      var r = 1 / v;
      if (isNaN(r) || !isFinite(r)) throw new Error('bad');
      show(r);
      expr = String(r);
    } catch (e) {
      show('Error');
      expr = '';
    }
  }

  function press(k) {
    if (display.value === 'Error') { expr = ''; }
    if (k === '=') { calc(); return; }
    if (k === '.') {
      if (expr === '') expr = '0.';
      else if (!/[.\d]$/.test(expr)) expr += '.';
    } else {
      expr += k;
    }
    show(expr);
  }

  Array.prototype.forEach.call(document.querySelectorAll('button[data-k]'), function (b) {
    b.addEventListener('click', function () { press(b.getAttribute('data-k')); });
  });

  document.getElementById('clear').addEventListener('click', function () {
    expr = '';
    show('0');
  });

  document.getElementById('sqrt').addEventListener('click', sqrt);
  document.getElementById('square').addEventListener('click', square);
  document.getElementById('reciprocal').addEventListener('click', reciprocal);
})();
</script>
</body>
</html>
END FILE

