      cert?: Buffer;

      /**
       * Path to the file with the private key in PEM format.
       */
      keyPath?: string;

      /**
       * Direct value of the private key in PEM format.
       */
      key?: Buffer;

      /**
       * Path to the PFX or PKCS12 encoded private key and certificate chain.
